import {personalReport} from './expedition-personal.mjs';
import {HEROES,SKILLS} from './expedition-data.mjs';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const advice={法力不足:'检查是否持续施放高耗蓝技能，并保留低耗蓝备用指令。防御耗蓝也会影响后续施法。',耗材耗尽:'核对全队共享补给与后续房间需求；考虑不消耗同种材料的备用技能。',装备条件不满足:'检查实际公会装备是否支持该技能，或改用不要求此装备的指令。'};
export function mountPersonalReport({onEvidence,onCamp,onHeroChange}){
 const root=document.createElement('section');root.id='personal-report';root.className='panel personal-report';document.querySelector('[data-replay-pane-content="review"]').prepend(root);
 let current=null,selected=null;
 const evidenceButton=(index,label)=>`<button data-personal-proof="${index}">${esc(label)} ↗</button>`;
 function render(report,heroId){current=report;selected=heroId;const p=personalReport(report,heroId),t=p.total,origin=report.perspective?.heroId,role=HEROES.find(h=>h.id===heroId).role;
 root.innerHTML=`<p class="eyebrow">我的远征 / ${p.name} · ${role}</p><div class="bar"><h2>这次远征，你留下了什么？</h2><label>观察角色 <select id="personal-hero">${HEROES.filter(h=>report.config.heroes.some(u=>u.id===h.id)).map(h=>`<option value="${h.id}" ${h.id===heroId?'selected':''}>${h.name} · ${h.role}</option>`).join('')}</select></label></div><p>${origin?'本次出征主角：'+HEROES.find(h=>h.id===origin).name+'（出发时记录）':'本战报没有主角身份记录；当前仅切换观察视角。'} 切换视角不改变公会主角。</p><div class="personal-metrics"><article><small>本人实伤</small><strong>${t.damage}</strong><span>召唤物另计 ${t.summonDamage}</span></article><article><small>有效治疗</small><strong>${t.healing}</strong><span>不含溢出治疗与道具</span></article><article><small>施加增益</small><strong>${t.buffApplications}</strong><span>按施放×对象计数，含自身与待生效</span></article><article><small>承受实伤</small><strong>${t.taken}</strong><span>得到技能治疗 ${t.received}</span></article><article><small>消耗法力</small><strong>${t.castMana+t.defenseMana+(t.interceptMana||0)}</strong><span>施法 ${t.castMana} / 防御 ${t.defenseMana}${t.interceptMana?' / 援护 '+t.interceptMana:''}</span></article><article><small>行动空过</small><strong>${t.failed}</strong><span>施放 ${t.casts} 次 / 道具 ${t.items} 次</span></article></div><p>本人消耗共享补给：药草 ${p.supplies.herb} · 符纸 ${p.supplies.rune} · 箭矢 ${p.supplies.arrow}。法力显示累计支付，不等于出发与结束的差额。</p>${t.interceptAttempts?`<p>援护尝试 ${t.interceptAttempts} 次 / 成功接招 ${t.interceptions||0} 次 / 支付 ${t.interceptMana} 法力；成功后仍正常防御和承伤，不换算为避免伤害。</p>`:''}${t.passiveRecords?`<p>缓释实际恢复 ${t.passiveHealing} · 未生效 ${t.passiveOverheal} · ${t.passiveRecords} 条目标恢复记录（含满血触发）。实际恢复已包含在总治疗中，未消耗普通救护行动。</p>`:''}${t.controlApplications||t.healingBlocks?`<p>施加负面 ${t.controlApplications} 次（挫志 ${t.weakeningApplications} / 禁疗 ${t.controlApplications-t.weakeningApplications}）；实际记录的自动救护受阻尝试 ${t.healingBlocks} 次。附着不保证目标随后尝试救护；受阻后仍可能执行普通攻击，未换算为避免治疗量。</p>`:''}${t.dispelledGroups?`<p>实际破除 ${t.dispelledGroups} 组技能增益 / ${t.dispelledEffects} 个组件（含待生效）；不换算成避免伤害或取消行动，来源仍可再次施放。</p>`:''}${t.cleansedEffects?`<p>实际净化 ${t.cleansedEffects} 个负面效果；不折算为避免伤害，已发生的攻击保留原结果。</p>`:''}<div class="personal-support">${[['我支援了谁',p.given],['谁支援了我',p.received]].map(([title,links])=>`<article><h3>${title}</h3>${links.map(l=>`<p><b>${l.name}</b> · 治疗 ${l.healing} / 增益 ${l.buffs} 次 ${l.healing?evidenceButton(l.healingIndex,'查看首次治疗'):''} ${l.buffs?evidenceButton(l.buffsIndex,'查看首次增益'):''}</p>`).join('')||`<p>${title==='我支援了谁'?'未记录到给予其他单位的技能治疗或增益。':'未记录到其他单位给予的技能治疗或增益。'}</p>`}</article>`).join('')}</div><p class="muted">增益次数不是收益排名，也未换算成“替队友增加的伤害”或“避免的伤害”。召唤物实伤独立展示；共享机关消耗按记录执行者归属。</p>${p.issues.length?`<section class="personal-issues"><h3>下一次可以检查</h3>${p.issues.map(i=>`<article><b>${SKILLS[i.skill]?.name||i.skill} · ${i.reason}</b><p>尝试跳过 ${i.count} 次。${advice[i.reason]} ${evidenceButton(i.index,'定位首次记录')}</p></article>`).join('')}<small>跳过尝试不等于行动空过：后续备用指令仍可能成功。建议需要再次出征验证。</small></section>`:'<p>未记录到本人因法力、耗材或装备条件跳过指令；这不代表配置已经最优。</p>'}<details><summary>逐房表现与代表记录</summary><div class="table-scroll"><table><thead><tr><th>房间</th><th>本人实伤</th><th>召唤实伤</th><th>治疗</th><th>增益</th><th>承伤</th><th>耗蓝</th><th>空过</th></tr></thead><tbody>${p.rooms.map(r=>`<tr><td>${esc(r.name)}</td><td>${r.damage}</td><td>${r.summonDamage}</td><td>${r.healing}</td><td>${r.buffApplications}</td><td>${r.taken}</td><td>${r.castMana+r.defenseMana}</td><td>${r.failed}</td></tr>`).join('')}</tbody></table></div><div class="personal-proof-list">${p.evidence.map(e=>evidenceButton(e.index,`${e.roomIndex+1}房 · ${e.kind}：${e.text}`)).join('')}</div></details><button data-personal-camp="true" class="primary">回营调整个人与伙伴 →</button>`;
 }
 root.onchange=e=>{if(e.target.id==='personal-hero'){render(current,e.target.value);onHeroChange(e.target.value);}};
 root.onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.personalProof!==undefined)onEvidence(Number(b.dataset.personalProof));if(b.dataset.personalCamp)onCamp();};
 return {render};
}
